"use client";

import { useCallback, useMemo } from "react";
import { Activity, CalendarClock, CheckCircle2, ClipboardList, Clock3, UserRound, Users, XCircle } from "lucide-react";
import { listPatients } from "@/lib/api/patient";
import { listDoctors } from "@/lib/api/doctor";
import { listAppointments } from "@/lib/api/appointment";
import { listNotifications } from "@/lib/api/notification";
import { usePolling } from "@/lib/hooks";
import { Appointment } from "@/lib/types";
import { StatusBadge } from "@/components/StatusBadge";

const cards = [
  ["patients", "Patients", Users, "text-teal bg-teal/10"],
  ["doctors", "Doctors", UserRound, "text-blue bg-blue/10"],
  ["appointments", "Appointments", ClipboardList, "text-navy bg-navy/10"],
  ["PENDING", "Pending", Clock3, "text-amber bg-amber/10"],
  ["CONFIRMED", "Confirmed", CheckCircle2, "text-blue bg-blue/10"],
  ["COMPLETED", "Completed", Activity, "text-green bg-green/10"],
  ["REJECTED", "Rejected", XCircle, "text-red bg-red/10"],
] as const;

export default function Dashboard() {
  const load = useCallback(async () => Promise.all([listPatients(), listDoctors(), listAppointments(), listNotifications()]), []);
  const { data, loading, error } = usePolling(load);
  const [patients, doctors, appointments, notifications] = data ?? [{ data: [] }, [], [], []] as const;
  const counts = useMemo(() => Object.fromEntries(["PENDING", "CONFIRMED", "COMPLETED", "REJECTED"].map((status) => [status, appointments.filter((item) => item.status === status).length])), [appointments]);
  const upcoming = appointments.filter((item) => item.status !== "COMPLETED" && item.status !== "REJECTED").sort((a, b) => `${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)).slice(0, 5);
  const max = Math.max(1, ...Object.values(counts));
  return <div className="space-y-7">
    <section className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-teal to-[#087f86] p-7 text-white shadow-card sm:p-9"><div className="relative z-10 max-w-xl"><p className="text-sm font-semibold text-white/75">Wednesday, October 21, 2026</p><h2 className="mt-2 text-3xl font-bold tracking-tight sm:text-4xl">Good morning, care team.</h2><p className="mt-3 text-sm leading-6 text-white/80">One connected view for patients, doctors, appointments, and every event that keeps care moving.</p></div><HeartGraphic /></section>
    {error && <div className="rounded-lg border border-red/20 bg-red/5 px-4 py-3 text-sm text-red">Some service data is unavailable. The dashboard will keep retrying automatically.</div>}
    <div className="grid grid-cols-2 gap-4 md:grid-cols-4 xl:grid-cols-7">{cards.map(([key, label, Icon, color]) => <div key={label} className="card p-4"><div className={`mb-4 grid h-10 w-10 place-items-center rounded-xl ${color}`}><Icon size={19} /></div><p className="text-2xl font-bold text-navy">{loading ? "—" : key === "patients" ? patients.data.length : key === "doctors" ? doctors.length : key === "appointments" ? appointments.length : counts[key]}</p><p className="mt-1 text-xs font-medium text-slate-500">{label}</p></div>)}</div>
    <div className="grid gap-6 xl:grid-cols-[1.3fr_1fr]"><section className="card p-6"><div className="mb-6 flex items-center justify-between"><div><h3 className="font-bold text-navy">Appointments by status</h3><p className="mt-1 text-xs text-slate-400">Live operational snapshot</p></div><CalendarClock className="text-teal" size={21} /></div><div className="space-y-5">{(["PENDING", "CONFIRMED", "COMPLETED", "REJECTED"] as const).map((status) => <div key={status} className="flex items-center gap-4"><span className="w-24 text-xs font-semibold text-slate-500">{status}</span><div className="h-3 flex-1 overflow-hidden rounded-full bg-canvas"><div className={`h-full rounded-full ${status === "PENDING" ? "bg-amber" : status === "CONFIRMED" ? "bg-blue" : status === "COMPLETED" ? "bg-green" : "bg-red"}`} style={{ width: `${(counts[status] / max) * 100}%` }} /></div><span className="w-6 text-right text-sm font-bold text-navy">{counts[status]}</span></div>)}</div></section><section className="card p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-bold text-navy">Upcoming appointments</h3><p className="mt-1 text-xs text-slate-400">Next in the care queue</p></div><Clock3 className="text-teal" size={21} /></div>{upcoming.length ? <div className="space-y-3">{upcoming.map((item) => <AppointmentRow key={item.id} item={item} />)}</div> : <Empty text="No upcoming appointments." />}</section></div>
    <section className="card p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-bold text-navy">Recent notifications</h3><p className="mt-1 text-xs text-slate-400">Latest event-driven updates</p></div><span className="rounded-full bg-teal/10 px-3 py-1 text-xs font-bold text-teal">{notifications.length} total</span></div>{notifications.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{notifications.slice(0, 6).map((item) => <div key={item.id} className="rounded-lg border border-line p-4"><div className="flex items-center justify-between gap-3"><StatusBadge status={item.status} /><span className="text-xs text-slate-400">{relative(item.createdAt)}</span></div><p className="mt-3 text-sm font-bold text-navy">{item.subject}</p><p className="mt-1 line-clamp-2 text-xs leading-5 text-slate-500">{item.message}</p></div>)}</div> : <Empty text="No notifications yet." />}</section>
  </div>;
}
function AppointmentRow({ item }: { item: Appointment }) { return <div className="flex items-center justify-between gap-3 rounded-lg border border-line p-3"><div className="min-w-0"><p className="truncate text-sm font-semibold text-navy">{item.patientName}</p><p className="mt-1 text-xs text-slate-500">Dr. {item.doctorName} · {item.date} at {item.time}</p></div><StatusBadge status={item.status} pulse={item.status === "PENDING"} /></div>; }
function Empty({ text }: { text: string }) { return <div className="rounded-lg bg-canvas px-4 py-8 text-center text-sm text-slate-400">{text}</div>; }
function relative(value: string) { const minutes = Math.max(1, Math.round((Date.now() - new Date(value).getTime()) / 60000)); return minutes < 60 ? `${minutes}m ago` : `${Math.round(minutes / 60)}h ago`; }
function HeartGraphic() { return <div className="absolute -right-8 -top-16 opacity-20"><svg width="350" height="300" viewBox="0 0 350 300" fill="none"><path d="M0 167h73l20-57 31 108 34-141 32 90h40l20-54 24 54h76" stroke="white" strokeWidth="5" /><circle cx="250" cy="120" r="90" stroke="white" strokeWidth="2" /></svg></div>; }
